<?php use PreConselho\Support\Csrf;$user=$_SESSION['user'];$canManage=in_array($user['perfil'],['ADMIN','COORDENADOR'],true);$types=['JORNADA_FORMATIVA'=>'Jornada formativa','CONSELHO_CLASSE'=>'Conselho de classe','EMENDA_FERIADO'=>'Emenda de feriado','EXCEPCIONAL'=>'Excepcional','OUTRO'=>'Outro'];$windowLabels=['ABERTA'=>'Disponível aos professores','AGUARDANDO'=>'Aguardando a data de abertura','AGUARDANDO_LIBERACAO'=>'Aguardando liberação da coordenação','ENCERRADA'=>'Encerrada','CANCELADA'=>'Cancelada'];ob_start();?>
<nav class="breadcrumbs" aria-label="Navegação estrutural"><a href="/apc">APCs</a> <span aria-hidden="true">›</span> <a href="/apc/calendario">Calendário</a> <span aria-hidden="true">›</span> Evento</nav>
<section class="page-heading"><div><p class="eyebrow">Evento APC</p><h1><?=e($event['titulo'])?></h1><p><?=e(date('d/m/Y',strtotime($event['data'])))?></p></div><span class="badge status-<?=e($window['state']==='ABERTA'?'aprovado':(in_array($window['state'],['AGUARDANDO','AGUARDANDO_LIBERACAO'],true)?'rascunho':'pendente'))?>"><?=e($windowLabels[$window['state']])?></span></section>
<section class="card"><dl class="event-detail-grid"><div><dt>Data</dt><dd><?=e(date('d/m/Y',strtotime($event['data'])))?></dd></div><div><dt>Tipo</dt><dd><?=e($types[$event['tipo']]??$event['tipo'])?></dd></div><div><dt>Origem</dt><dd><?=e($event['origem'])?></dd></div><div><dt>Janela permitida</dt><dd><?=e(date('d/m/Y',strtotime($window['opens_on'])))?> a <?=e(date('d/m/Y',strtotime($window['closes_on'])))?></dd></div><?php if($event['numero_processo']):?><div><dt>Processo</dt><dd><?=e($event['numero_processo'])?></dd></div><?php endif;?><?php if($event['documento_referencia']):?><div><dt>Fonte oficial</dt><dd><?=e($event['documento_referencia'])?><?=$event['fonte_pagina']?' · p. '.e($event['fonte_pagina']):''?></dd></div><?php endif;?></dl><h2>Descrição</h2><p><?=e($event['descricao']?:'Sem descrição adicional.')?></p><?php if(!$window['is_open']):?><p class="subtle-box"><?php if($window['state']==='AGUARDANDO_LIBERACAO'):?>A data já permite o preenchimento, mas a APC ainda precisa ser disponibilizada pela coordenação.<?php else:?>Esta APC está disponível somente para consulta. O preenchimento depende da janela indicada e da liberação da coordenação.<?php endif;?></p><?php endif;?></section>
<?php if($canManage):?><section class="card"><div class="section-heading"><div><p class="eyebrow">Controle da coordenação</p><h2>Disponibilidade para os professores</h2><?php if($window['state']==='ABERTA'):?><p>Os professores já podem preencher esta APC até <?=e(date('d/m/Y',strtotime($window['closes_on'])))?>.</p><?php elseif($window['state']==='AGUARDANDO_LIBERACAO'):?><p>A janela está válida. Use o botão para liberar o preenchimento aos professores.</p><?php elseif($window['state']==='AGUARDANDO'):?><p>A liberação será permitida a partir de <?=e(date('d/m/Y',strtotime($window['opens_on'])))?>.</p><?php elseif($window['state']==='ENCERRADA'):?><p>O prazo terminou em <?=e(date('d/m/Y',strtotime($window['closes_on'])))?> e não pode mais ser liberado.</p><?php else:?><p>Eventos cancelados não podem ser disponibilizados.</p><?php endif;?></div><?php if($window['state']==='AGUARDANDO_LIBERACAO'):?><form class="inline-form" method="post" action="/apc/eventos/<?=e($event['id'])?>/disponibilizar"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="retorno" value="evento"><button class="primary" data-confirm="Disponibilizar esta APC aos professores?">Disponibilizar aos professores</button></form><?php elseif($window['state']==='ABERTA'):?><form class="inline-form" method="post" action="/apc/eventos/<?=e($event['id'])?>/suspender"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="retorno" value="evento"><button data-confirm="Suspender agora o preenchimento desta APC?">Suspender acesso</button></form><?php endif;?></div></section><?php endif;?>
<?php if($user['perfil']==='PROFESSOR'):?><section class="card"><div class="section-heading"><div><h2>Meus planos neste evento</h2><p>Somente seus próprios planos são exibidos.</p></div><?php if($window['is_open']):?><a class="button primary" href="/apc/planos/novo?evento=<?=e($event['id'])?>">Criar plano</a><?php endif;?></div><?php if($teacherPlans):?><div class="table"><table><thead><tr><th>Turma</th><th>Componente(s)</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($teacherPlans as$plan):?><tr><td><?=e($plan['turma_nome_snapshot'])?></td><td><?=e($plan['componente_curricular'])?></td><td><?=e($plan['status'])?></td><td><a class="button small-button" href="/apc/planos/<?=e($plan['id'])?>"><?=$plan['status']==='RASCUNHO'&&$window['is_open']?'Continuar':'Visualizar'?></a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>Nenhum plano seu foi criado para este evento.</p><?php endif;?></section><?php else:?><section class="card"><h2>Resumo dos planos</h2><div class="metrics"><article class="metric static"><span class="metric-label">Criados</span><strong><?=e((int)$summary['total'])?></strong></article><article class="metric static status-card-aprovado"><span class="metric-label">Finalizados</span><strong><?=e((int)$summary['finalizados'])?></strong></article><article class="metric static status-card-rascunho"><span class="metric-label">Pendentes</span><strong><?=e((int)$summary['pendentes'])?></strong></article></div></section><?php endif;?>
<?php $content=ob_get_clean();require dirname(__DIR__,3).'/preconselho-web/resources/views/layout.php';
